mapper.select:

SELECT
  count(*) totcnt
FROM
  ttokssaemdb.notice notice


    AND notice.branchid = #{session_branchid}


    AND notice.message LIKE #{likeQuery}

SELECT R1.* FROM( SELECT branch.branchid, branch.branchname, member.memberid, member.membername, notice.category, notice.title, notice.message, notice.readyn, DATE_FORMAT(notice.regdate, '%Y-%m-%d %H:%i:%s') regdate FROM ttokssaemdb.notice notice, ttokssaemdb.branch branch, ttokssaemdb.member member
AND notice.branchid = branch.branchid AND notice.memberid = member.memberid
AND notice.branchid = #{session_branchid}
AND user.username LIKE #{likeQuery}
notice.noticeid notice.category notice.title notice.readyn notice.regdate DESC ASC DESC
) R1
LIMIT ${length} OFFSET ${start}
